coeff('A.12',23,'K4',[('计算工件尺寸≤300 mm',0.),('计算工件尺寸>300～450 mm',.2),('计算工件尺寸>450～600 mm',.5),('计算工件尺寸>600～800 mm',1.),('计算工件尺寸>800～1000 mm',2.5),('计算工件尺寸>1000 mm',3.)])
for i,r in enumerate(rows,1):
    r['record_id']=f'GBT36561-2018-T{r["table"]}-{i:04d}'
    v,t,m,b=r['value'],r['table'],r['metric'],r['branch']
    if isinstance(v,(int,float)):
        precision=0 if float(v).is_integer() else len(str(v).split('.')[1])
        if t=='1' and '仪表' in m:precision=1
        if t=='3' and ('百分数' in m):precision=2 if v in [.38,.75] else 1
        if t=='5':precision=2
        if t=='9' and m=='α':precision=2
        if t=='11':precision=1
        if t=='13' and b=='铅':precision=2
        if t=='13' and b in ['汞','铍及其化合物(以Be计)']:precision=3
        if t=='14' and b.split(' ')[0] in ['4','5','7','8','9','10','11','12']:precision=1
        if t.startswith('A.'):
            precision=1
            if t=='A.1' and v>=1:precision=2
            if t=='A.4' and v==1:precision=0
            if t=='A.7' and v==.81:precision=2
        r['source_numeric_text']=f'{v:.{precision}f}'
    else:r['source_numeric_text']=str(v)
ROOT.joinpath('data').mkdir(exist_ok=True)
ROOT.joinpath('evidence').mkdir(exist_ok=True)
ROOT.joinpath('data/table_values.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
with ROOT.joinpath('data/table_values.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
print(json.dumps({'records':len(rows),'tables':len(set(r['table'] for r in rows)),'numeric_values':sum(isinstance(r['value'],(int,float)) for r in rows)},ensure_ascii=False))
